150	  if (r.error !== undefined) {
151	    throw new ExecutionError(`${name} を実行できない (${bin}): ${r.error.message}`);
152	  }
153	  const output = `${r.stdout}${r.stderr}`.trimEnd();
154	  if (r.status === 0) return { ok: true, output };
155	  if (r.status !== null && findingCodes.includes(r.status)) return { ok: false, output };
156	  throw new ExecutionError(
157	    `${name} が終了コード ${String(r.status)} (シグナル ${String(r.signal)}) で終了した (${bin}):\n${output}`,
158	  );
159	}
160	
161	/** tsc で、build/tsconfig.json の資料ごとのスクリプトを検査する */
162	export function typeCheck(paths: DeckPaths, cache: CachePaths, env: NodeJS.ProcessEnv): ToolResult {
163	  // tsc は、型の誤りがあれば、noEmit でも終了コード 1 か 2 を返す (2 は出力を生成した場合だが、区別しない)
164	  return runBin(cache, "tsc", ["-p", paths.tsconfig, "--pretty", "false"], paths.deckDir, env, [1, 2]);
165	}
166	
167	/** eslint で、資料ごとのスクリプトを検査する (設定は、プラグインのファイル src/check/eslint.deck.config.mjs) */
168	export function lint(paths: DeckPaths, cache: CachePaths, env: NodeJS.ProcessEnv, pluginDir: string = PLUGIN_DIR): ToolResult {
169	  const config = join(pluginDir, "src", "check", "eslint.deck.config.mjs");
170	  return runBin(
171	    cache,
172	    "eslint",
173	    ["--config", config, paths.script],
174	    paths.deckDir,
175	    { ...env, SLIDE_DECK_NODE_MODULES: cache.nodeModulesDir, SLIDE_DECK_TSCONFIG: paths.tsconfig },
176	    // eslint の終了コード 1 は指摘あり、2 は設定の誤りなどの実行の誤り
177	    [1],
178	  );
179	}
180	
181	/** 資料ごとのスクリプトを実行した結果。実行できなければ、message に理由がある */
182	export type LoadResult = { ok: true; result: DeckScriptResult } | { ok: false; message: string };
183	
184	/**
185	 * 資料ごとのスクリプトを import し、default export の関数に部品の関数の集まりを渡して実行する。
186	 * tsc で型を検査した後に呼ぶ。実行の途中の例外は、資料ごとのスクリプトの誤りとして返す
187	 */
188	export async function loadDeckScript(paths: DeckPaths): Promise<LoadResult> {
189	  try {
190	    const mod: unknown = await import(pathToFileURL(paths.script).href);
191	    const fn: unknown = typeof mod === "object" && mod !== null && "default" in mod ? mod.default : undefined;
192	    if (typeof fn !== "function") {
193	      return { ok: false, message: "deck.ts が、関数を default export していない" };
194	    }
195	    // 型は、build/deck-type.ts で tsc が DeckScript であることを検査した
196	    const result = (fn as DeckScript)(parts);
197	    return { ok: true, result };
198	  } catch (e) {
199	    return { ok: false, message: e instanceof Error ? (e.stack ?? e.message) : String(e) };
200	  }
201	}
202	
203	/**
204	 * 構成案と、資料ごとのスクリプトの結果から、スライドのデータを作る。キーが一致していることを確認した後に呼ぶ。
205	 * スライドの順序は構成案の順序。題名・一言・発表者ノートは構成案から、図は資料ごとのスクリプトから取る (計画の R8)
206	 */
207	export function assembleDeck(outline: DeckOutline, result: DeckScriptResult): Deck {
208	  const figures = new Map(result.slides.map((f) => [f.key, f]));
209	  return {
210	    title: outline.title,
211	    theme: result.theme,
212	    slides: outline.slides.map((s) => {
213	      const figure = figures.get(s.key);
214	      if (figure === undefined) throw new Error(`資料ごとのスクリプトに、キー ${s.key} の図が無い`);
215	      return { key: s.key, title: s.title, takeaway: s.takeaway, notes: s.notes, elements: figure.elements };
216	    }),
217	  };
218	}
219	
220	/** 検査の指摘の 1 つの種類。heading は種類の見出し、lines はその指摘 */
221	export interface Finding {
222	  readonly heading: string;
223	  readonly lines: readonly string[];
224	}
225	
226	/** 検査の結果。指摘が無ければ deck にスライドのデータがあり、指摘があれば deck は null */
227	export interface CheckReport {
228	  readonly findings: readonly Finding[];
229	  readonly deck: Deck | null;
230	}
231	
232	/** はみ出しそうな箇所の要素を、利用者に示す名前にする */
233	function describeFitElement(e: FitIssue["element"]): string {
234	  if (e === "title") return "題名";
235	  if (e === "takeaway") return "一言";
236	  return `deck.ts の要素 ${String(e)} (スライドの要素の配列の添字。足した順に 0 から数える)`;
237	}
238	
239	function formatFitIssue(i: FitIssue): string {
240	  return `${i.key} の${describeFitElement(i.element)}: 要る高さ ${i.need.toFixed(2)} インチ、文字を置ける高さ ${i.height.toFixed(2)} インチ、文字の先頭 ${JSON.stringify(i.head)}`;
241	}
242	
243	/**
244	 * 資料のディレクトリを検査する。検査の順序と、指摘があったときに後の検査をするかは次のとおり。
245	 * 1. 構成案の書式と【提案】の残り。
246	 * 2. tsc と eslint。どちらかに指摘があれば、資料ごとのスクリプトを実行せずに終える。
247	 * 3. 資料ごとのスクリプトの実行と、テーマの値。
248	 * 4. 構成案と資料ごとのスクリプトのキーの突き合わせ (構成案に書式の誤りが無いときだけ)。
249	 * 5. はみ出しの見積もり (キーが一致し、テーマに誤りが無いときだけ)。
250	 * 資料のディレクトリやファイルが無い・ライブラリが入っていない・ツールを実行できないときは、ExecutionError を送出する
251	 */
252	export async function checkDeck(deckDir: string, options: CheckOptions = {}): Promise<CheckReport> {
253	  const pluginDir = options.pluginDir ?? PLUGIN_DIR;
254	  const env = options.env ?? process.env;
255	  const paths = deckPaths(deckDir);
256	  const cache = installedCache({ pluginDir, env });
257	  prepareBuildDir(paths, pluginDir);
258	  const findings: Finding[] = [];
259	
260	  const parsed = parseOutline(readFileSync(paths.outline, "utf8"));
261	  if (!parsed.ok) {
262	    findings.push({ heading: "構成案 outline.md の書式の誤り", lines: parsed.errors.map(formatOutlineError) });
263	  } else if (parsed.outline.proposals.length > 0) {
264	    findings.push({
265	      heading: "【提案】が付いたままのスライド (採否を決め、採用するなら【提案】を外し、採用しないならスライドを消す)",
266	      lines: parsed.outline.proposals.map((s) => `${String(s.line)} 行目: ${s.key}: ${s.title}`),
267	    });
268	  }
269	
270	  const tsc = typeCheck(paths, cache, env);
271	  if (!tsc.ok) findings.push({ heading: "tsc の指摘", lines: tsc.output.split("\n") });
272	  const eslint = lint(paths, cache, env, pluginDir);
273	  if (!eslint.ok) findings.push({ heading: "eslint の指摘", lines: eslint.output.split("\n") });
274	  if (!tsc.ok || !eslint.ok) return { findings, deck: null };
275	
276	  const loaded = await loadDeckScript(paths);
277	  if (!loaded.ok) {
278	    findings.push({ heading: "deck.ts を実行できない", lines: loaded.message.split("\n") });
279	    return { findings, deck: null };
280	  }
281	  const themeErrors = checkTheme(loaded.result.theme);
282	  if (themeErrors.length > 0) findings.push({ heading: "deck.ts のテーマの誤り", lines: themeErrors });
283	  if (!parsed.ok) return { findings, deck: null };
284	
285	  const outline = parsed.outline;
286	  const mismatch = matchKeys(
287	    outline.slides.map((s) => s.key),
288	    loaded.result.slides.map((f) => f.key),
289	  );
290	  if (hasMismatch(mismatch)) {
291	    const lines: string[] = [];
292	    if (mismatch.outlineOnly.length > 0) lines.push(`構成案にだけあるキー: ${mismatch.outlineOnly.join(", ")}`);
293	    if (mismatch.deckOnly.length > 0) lines.push(`deck.ts にだけあるキー: ${mismatch.deckOnly.join(", ")}`);
294	    if (mismatch.deckDuplicates.length > 0) {
295	      lines.push(`deck.ts で 2 回以上図を作ったキー: ${mismatch.deckDuplicates.join(", ")}`);
296	    }
297	    findings.push({ heading: "構成案と deck.ts のキーの不一致", lines });
298	    return { findings, deck: null };
299	  }
300	  if (themeErrors.length > 0) return { findings, deck: null };
301	
302	  const deck = assembleDeck(outline, loaded.result);
303	  const fit = estimateSlides(deck.slides);
304	  if (fit.length > 0) {
305	    findings.push({ heading: "文字が箱からはみ出しそうな箇所 (箱を広げるか、文を縮める)", lines: fit.map(formatFitIssue) });
306	  }
307	  return { findings, deck: findings.length === 0 ? deck : null };
308	}
309	
310	/** 検査の結果を、利用者に示す文字列にする。指摘が無ければ、スライドの枚数を示す */
311	export function formatCheckReport(report: CheckReport): string {
312	  if (report.deck !== null) {
313	    return `検査の指摘は無い (スライド ${String(report.deck.slides.length)} 枚)\n`;
314	  }
315	  return report.findings.map((f) => `${f.heading}:\n${f.lines.map((l) => `  ${l}`).join("\n")}\n`).join("\n");
316	}
