18	/** 実行の誤り (資料のディレクトリやファイルが無い・ライブラリが入っていない・ツールを実行できないなど)。入口は終了コード 2 にする */
19	export class ExecutionError extends Error {
20	  override name = "ExecutionError";
21	}
