31	/** 資料のディレクトリの中のファイルのパス */
32	export interface DeckPaths {
33	  readonly deckDir: string;
34	  /** 構成案 outline.md */
35	  readonly outline: string;
36	  /** 資料ごとのスクリプト deck.ts */
37	  readonly script: string;
38	  /** 生成したファイルを書き込むディレクトリ build/ */
39	  readonly buildDir: string;
40	  /** build/.gitignore (計画の KTD15) */
41	  readonly gitignore: string;
42	  /** build/tsconfig.json (計画の KTD2) */
43	  readonly tsconfig: string;
44	  /** build/deck-type.ts (deck.ts の default export の型を tsc で検査するファイル) */
45	  readonly typeCheck: string;
46	}
