91	// build/deck-type.ts の内容。deck.ts に default export が無いときや、型 DeckScript に合わないときに、tsc が指摘する
92	const TYPE_CHECK_SOURCE = `// プラグイン slide-deck のサブコマンド check が書くファイル。
93	// 資料ごとのスクリプト deck.ts の default export が、型 DeckScript であることを tsc で検査する。
94	import type { DeckScript } from "slide-deck";
95	import deck from "../deck.ts";
96	
97	deck satisfies DeckScript;
98	`;
