100	/**
101	 * 資料のディレクトリに build/ を作り、.gitignore・tsconfig.json・deck-type.ts を書く (計画の KTD2・KTD15)。
102	 * tsconfig.json は、プラグインの tsconfig.json の compilerOptions を使い、名前 slide-deck をプラグインの型に対応させる。
103	 * 型の定義は、types を空にして、資料のディレクトリより上にある @types を読み込まない
104	 * (資料ごとのスクリプトは、Node.js の機能を使わず、部品の関数でスライドのデータを作るだけにするため)。
105	 */
106	export function prepareBuildDir(paths: DeckPaths, pluginDir: string = PLUGIN_DIR): void {
107	  mkdirSync(paths.buildDir, { recursive: true });
108	  // 生成したファイルが、プロジェクトのコミットに入らないようにする。プロジェクトの .gitignore は変えない
109	  writeFileSync(paths.gitignore, "*\n");
110	  const pluginTsconfig: unknown = JSON.parse(readFileSync(join(pluginDir, "tsconfig.json"), "utf8"));
111	  if (typeof pluginTsconfig !== "object" || pluginTsconfig === null || !("compilerOptions" in pluginTsconfig)) {
112	    throw new ExecutionError(`プラグインの ${join(pluginDir, "tsconfig.json")} に compilerOptions が無い`);
113	  }
114	  const base: unknown = pluginTsconfig.compilerOptions;
115	  if (typeof base !== "object" || base === null) {
116	    throw new ExecutionError(`プラグインの ${join(pluginDir, "tsconfig.json")} の compilerOptions がオブジェクトではない`);
117	  }
118	  const tsconfig = {
119	    compilerOptions: {
120	      ...base,
121	      types: [],
122	      paths: { "slide-deck": [join(pluginDir, "src", "index.ts")] },
123	    },
124	    files: ["../deck.ts", "deck-type.ts"],
125	  };
126	  writeFileSync(paths.tsconfig, `${JSON.stringify(tsconfig, null, 2)}\n`);
127	  writeFileSync(paths.typeCheck, TYPE_CHECK_SOURCE);
128	}
