// 資料ごとのスクリプト deck.ts が、名前 slide-deck で import type する型 (計画の KTD2)。
// deck.ts はプラグインのモジュールを実行時に import しないので、ここからは型だけを書き出す。

import type { Parts } from "./data/parts.ts";
import type { SlideFigure } from "./data/types.ts";
import type { Theme } from "./data/theme.ts";

export type {
  ArrowOptions,
  BadgeOptions,
  BoxOptions,
  BulletsOptions,
  CardOptions,
  MarginInput,
  Parts,
  RunInput,
  TextOptions,
} from "./data/parts.ts";
export type { AccentColor, SchemeColorName, Theme } from "./data/theme.ts";
export type {
  Deck,
  Fill,
  LineElement,
  Margin,
  Outline,
  Paragraph,
  Rect,
  ShapeElement,
  ShapeGeometry,
  ShapeKind,
  Slide,
  SlideElement,
  SlideFigure,
  TextBody,
  TextBoxElement,
  TextRun,
  ThemeColorName,
} from "./data/types.ts";

/** 資料ごとのスクリプトの関数が返す値。資料のテーマと、キーごとの図。 */
export interface DeckScriptResult {
  theme: Theme;
  slides: SlideFigure[];
}

/**
 * 資料ごとのスクリプトが default export する関数の型。
 * 部品の関数の集まりを引数で受け取り、テーマとキーごとの図を返す。
 */
export type DeckScript = (p: Parts) => DeckScriptResult;
{
  "compilerOptions": {
    "target": "es2024",
    "lib": ["es2024"],
    "module": "preserve",
    "moduleResolution": "bundler",
    "types": ["node"],
    "strict": true,
    "noEmit": true,
    "allowImportingTsExtensions": true,
    "erasableSyntaxOnly": true,
    "verbatimModuleSyntax": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitOverride": true,
    "noPropertyAccessFromIndexSignature": true,
    "skipLibCheck": true,
    "paths": {
      "slide-deck": ["./src/index.ts"]
    }
  },
  "include": ["src", "tests", "examples"]
}
// 構成案 outline.md を読み、資料の情報とスライドごとのキー・題名・一言・図の説明・発表者ノートを取り出す (計画の KTD13)。
// 書式に合わない行は、行番号を付けた誤りにする。最初の誤りで中断せず、すべての誤りを集めてから返す。
//
// 構成案の書式:
//
//   # <資料の題名>
//
//   - 読者: <値>
//   - ねらい: <値>
//   - 形: <値>
//   - 固有名: 一般化する | そのまま書く          (省略できる)
//   - Google スライド: <資料の URL>               (省略できる)
//   - slide-deck の版: <数.数.数>                 (省略できる)
//
//   ## <章の名前>                                  (省略できる)
//
//   ### <キー>: <題名>
//   - 図: <図の説明>
//     <字下げした行も、図の説明に含める>
//   - 一言: <そのスライドで伝えたいことの 1 文>
//
//   <発表者ノートの段落>
//
// - 題名の行の前と、資料の情報の行の間には、空行だけを書ける。
// - 採否を利用者に質問するスライドは、見出しを ### 【提案】<キー>: <題名> にする (計画の R3)。
// - キーは英小文字・数字・ハイフンの 1〜32 文字 (計画の KTD9)。資料の中で 1 つにする。
// - スライドの見出しの下には、まず - 図: と - 一言: の行を 1 回ずつ書く。ほかの項目は書けない。
// - 箇条書きの後に空行を 1 行以上空けて、発表者ノートの段落を書く。ノートは省略できる。
//   ノートは地の文だけにする。- で始まる行と字下げした行は書けない。
// - 章は省略できる。章を書くなら、スライドを 1 枚以上入れる。
// - 区切りの線 (---) は、どこにも書けない。
// - #### 以下の見出しは書けない。

/** 構成案の書式の誤り。line は 1 から数えた行番号。 */
export interface OutlineError {
  line: number;
  message: string;
}

/** 誤りを「<行番号> 行目: <内容>」の形の 1 行にする。 */
export function formatOutlineError(e: OutlineError): string {
  return `${String(e.line)} 行目: ${e.message}`;
}

/** 資料の情報の項目「固有名」の値 (計画の R4)。 */
export type ProperNouns = "一般化する" | "そのまま書く";

const PROPER_NOUNS: readonly ProperNouns[] = ["一般化する", "そのまま書く"];

/** 資料の情報の項目「Google スライド」の値。presentationId は URL の /d/ の後の、資料の ID。 */
export interface GoogleSlidesRef {
  url: string;
  presentationId: string;
}

/** 構成案の先頭の、資料の情報。省略できる項目は、書いていなければ null。 */
export interface OutlineInfo {
  /** 読者 */
  audience: string;
  /** ねらい */
  purpose: string;
  /** 形 */
  form: string;
  /** 固有名 */
  properNouns: ProperNouns | null;
  /** Google スライド */
  googleSlides: GoogleSlidesRef | null;
  /** slide-deck の版 (最後に publish したプラグインの版) */
  pluginVersion: string | null;
}

/** 構成案の 1 枚のスライド。 */
export interface OutlineSlide {
  key: string;
  title: string;
  /** 一言 */
  takeaway: string;
  /** 図の説明。- 図: の行の後の字下げした行も、改行で区切って含める。 */
  figure: string;
  /** 発表者ノート。段落の中の改行は残し、段落の間は空行 1 つ (\n\n) にする。ノートが無ければ空の文字列。 */

